#!/usr/bin/env bash
# HOST-01 step 10. One database backup: dump, compress, keep a local copy, and
# send it off the machine. Run by trialoom-backup.timer; safe to run by hand:
#   ssh -i ~/.ssh/trialoom_hetzner root@<host> 'bash /opt/trialoom/runners/backup.sh'
# Evidence already lives in the bucket, so this covers the database and nothing
# else. The credentials in /etc/trialoom are deliberately NOT backed up: they are
# regenerated by the setup scripts, except BETTER_AUTH_SECRET, whose loss only
# invalidates existing sessions.
set -euo pipefail
test "$(id -u)" = 0
LOCAL_DIR="${LOCAL_DIR:-/var/backups/trialoom}"
KEEP_DAYS="${KEEP_DAYS:-14}"
APP_DIR="${APP_DIR:-/opt/trialoom}"

set -a; . /etc/trialoom/db.env; . /etc/trialoom/s3.env; set +a
install -d -m 700 "$LOCAL_DIR"
stamp="$(date -u +%Y%m%dT%H%M%SZ)"
file="$LOCAL_DIR/trialoom-$stamp.sql.gz"

umask 077
pg_dump --no-owner --no-privileges --format=plain "$DATABASE_URL" | gzip -9 > "$file"
test -s "$file"
gzip -t "$file"
chmod 600 "$file"

cd "$APP_DIR"
node scripts/backup-upload.ts "$file" --keep-days "$KEEP_DAYS"

# Local copies are a convenience for a fast restore, not the backup itself.
find "$LOCAL_DIR" -name 'trialoom-*.sql.gz' -mtime "+$KEEP_DAYS" -delete
